solutionCode:
export function classificarNumero(valor) {
  return new Promise((resolve, reject) => {
    if (typeof valor !== 'number') {
      reject(new Error('não é um número'));
      return;
    }
    if (valor > 0) {
      resolve('positivo');
      return;
    }
    if (valor < 0) {
      resolve('negativo');
      return;
    }
    resolve('zero');
  });
}
